        core = v
        pre = None
        plus_idx = core.find('+')
        if plus_idx != -1:
            core = core[:plus_idx]
        dash_idx = core.find('-')
        if dash_idx != -1:
            pre = core[dash_idx+1:]
            core = core[:dash_idx]
        major, minor, patch = (int(x) for x in core.split('.'))
        return major, minor, patch, pre

    def pre_key(pre):
        if pre is None:
            return None
        idents = pre.split('.')
        key = []
        for ident in idents:
            if ident.isdigit():
                key.append((0, int(ident), ''))
            else:
                key.append((1, 0, ident))
        return key

    def cmp_pre(a, b):
        if a is None and b is None:
            return 0
        if a is None:
            return 1
        if b is None:
            return -1
