        kb = pre_key(b)
        for x, y in zip(ka, kb):
            if x < y:
                return -1
            if x > y:
                return 1
        if len(ka) < len(kb):
            return -1
        if len(ka) > len(kb):
            return 1
        return 0

    import functools

    def cmp(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        for i in range(3):
            if p1[i] != p2[i]:
                return -1 if p1[i] < p2[i] else 1
        return cmp_pre(p1[3], p2[3])

    return sorted(versions, key=functools.cmp_to_key(cmp))

